+            Some(receipt) => {
+                tx_hash_from_receipt(&receipt).map_err(|e| e.into_settlement_error(network))
+            }
+            None => {
+                store
+                    .insert(
+                        key,
+                        PendingSettlement {
+                            tx_hash,
+                            request_hash,
+                        },
+                    )
